func:
if (!Array.isArray(msg.payload) || msg.payload.length === 0) {
    node.warn("No PIS_REJECT lots for selected date");
    return null;
}

var sendDate =
    String(
        msg.sendDate ||
        global.get("sendAllRejectDate") ||
        ""
    ).trim();

if (!sendDate) {
    node.error("Reject sendDate missing");
    return null;
}

var queue = msg.payload.map(function (r) {
    return {
        lotNo: String(r.LotDepID || "").trim(),

        sendDate: sendDate,

        lastDt: r.LastDt || null,

        status: "WAITING",
        sendQty: 0,
        message: ""
    };
});

flow.set("pisRejectAutoQueue", queue);
flow.set("pisRejectAutoIndex", 0);


msg.payload = true;

return msg;

var queue =
    flow.get("pisRejectAutoQueue") || [];

var index =
    Number(
        flow.get("pisRejectAutoIndex") || 0
    );


// =====================================================
// FINISHED ALL LOTS
// =====================================================

if (index >= queue.length) {




    // ---------------------------------------------
    // Summary
    // ---------------------------------------------

    var successCount = 0;
    var errorCount = 0;
    var skipCount = 0;

    var successLots = [];
    var errorLots = [];


    queue.forEach(function (item) {

        var status =
            String(
                item.status || ""
            ).trim();

        var lotNo =
            String(
                item.lotNo || ""
            ).trim();


        // -----------------------------------------
        // SUCCESS
        // -----------------------------------------

        if (status === "SUCCESS") {

            successCount++;

            if (lotNo) {
                successLots.push(lotNo);
            }
        }


        // -----------------------------------------
        // ERROR
        // -----------------------------------------

        else if (status === "ERROR") {

            errorCount++;

            if (lotNo) {
                errorLots.push(lotNo);
            }
        }


        // -----------------------------------------
        // SKIP
        //
        // เช่น:
        // ALREADY SENT
        // PIS / LOCAL MISMATCH
        // NO DELTA
        // DUPLICATE BLOCKED
        // ฯลฯ
        // -----------------------------------------

        else {

            skipCount++;
        }
    });


    // =================================================
    // RESULT TEXT
    // =================================================

    var resultText =
        "REJECT | DONE " +
        queue.length +
        " Lots" +
        " | SUCCESS " +
        successCount +
        " | SKIP " +
        skipCount +
        " | ERROR " +
        errorCount;


    // ---------------------------------------------
    // แสดง Lot ที่ POST สำเร็จจริง
    // ---------------------------------------------

    if (successLots.length > 0) {

        resultText +=
            " | Sent Lots: " +
            successLots.join(", ");
    }


    // ---------------------------------------------
    // ถ้ามี ERROR ให้แสดง Lot ด้วย
    // ---------------------------------------------

    if (errorLots.length > 0) {

        resultText +=
            " | Error Lots: " +
            errorLots.join(", ");
    }


    // =================================================
    // UI MESSAGE
    // output 2 -> Reject msg
    // =================================================

    var uiMsg = {

        payload:
            resultText,

        rejectBatchResult: {

            done:
                true,

            total:
                queue.length,

            success:
                successCount,

            skip:
                skipCount,

            error:
                errorCount,

            successLots:
                successLots,

            errorLots:
                errorLots,

            queue:
                queue
        }
    };


    // =================================================
    // NODE STATUS
    // =================================================

    node.status({

        fill:
            errorCount > 0
                ? "red"
                : "green",

        shape:
            "dot",

        text:
            "DONE " +
            queue.length +
            " Lots" +
            " | SENT " +
            successCount
    });


    return [
        null,
        uiMsg
    ];
}


// =====================================================
// PROCESS CURRENT LOT
// =====================================================

var item =
    queue[index];

item.status =
    "CHECKING";

queue[index] =
    item;

flow.set(
    "pisRejectAutoQueue",
    queue
);


msg.autoBatch = {

    index:
        index,

    lotNo:
        item.lotNo,

    sendDate:
        item.sendDate
};

msg.lotNo =
    item.lotNo;

msg.sendDate =
    item.sendDate;


node.status({

    fill:
        "blue",

    shape:
        "dot",

    text:
        (index + 1) +
        "/" +
        queue.length +
        " " +
        item.lotNo
});


return [
    msg,
    null
];

var lotNo = String(
    msg.lotNo ||
    (msg.autoBatch && msg.autoBatch.lotNo) ||
    ""
).trim();

var sendDate = String(
    msg.sendDate ||
    (msg.autoBatch && msg.autoBatch.sendDate) ||
    global.get("sendAllRejectDate") ||
    ""
).trim();

if (!lotNo) {
    node.error("Batch LotNo missing");
    return null;
}

if (!sendDate) {
    node.error("Batch sendDate missing for " + lotNo);
    return null;
}

var safeLot =
    lotNo.replace(/'/g, "''");

var safeDate =
    sendDate.replace(/'/g, "''");

msg.topic = `
SELECT TOP 1
     P.[Prod Date] AS productionDate
    ,P.[Shift] AS shiftCode
    ,P.[Plant] AS plantCode
    ,P.[Machine] AS Machine
    ,TRIM(P.[Lot No.]) AS lotNo
    ,P.[CuringCnt] AS gross0
    ,P.[Start Time] AS dateTimeStart
    ,P.[End Time] AS dateTimeEnd
    ,P.[MaterialCode] AS materialCode
FROM PIS_PRD_ORDER P
WHERE TRIM(P.[Lot No.]) = '${safeLot}'
  AND CAST(P.[Prod Date] AS date) <= '${safeDate}'
ORDER BY
     P.[Prod Date] DESC,
     P.[Start Time] DESC
`;

return msg;

if (!Array.isArray(msg.payload) || msg.payload.length === 0) {
    node.error("Production Header not found for " + msg.lotNo);
    return null;
}

var header = msg.payload[0];

function formatDate(d) {
    if (!d) return "";
    return new Date(d).toISOString().split("T")[0];
}

// เก็บ state ของ batch ไว้ใน msg
msg.batchState = msg.batchState || {};

msg.batchState.index =
    msg.autoBatch.index;

msg.batchState.lotNo =
    String(header.lotNo || msg.lotNo).trim();

msg.batchState.header =
    header;

msg.payload = {
    PlantCode:
        String(header.plantCode || "").trim(),

    MachineCode:
        String(header.Machine || "").trim(),

    DateFrom:
        formatDate(header.productionDate),

    DateTo:
        formatDate(header.productionDate),

    LotNumbers:
        String(header.lotNo || msg.lotNo).trim()
};

return msg;

var data = msg.payload;

if (!msg.batchState || !msg.batchState.header) {
    node.error("BATCH header missing");
    return null;
}

var header = msg.batchState.header;

if (!Array.isArray(data)) {
    node.error("OutputDetails is not array");
    return null;
}

var originalQty = Number(header.gross0 || 0);

if (originalQty < 0) {
    originalQty = 0;
}

var summary = {
    originalQty: originalQty,
    stockyard: 0,
    rejects: {},
    totalReject: 0,
    totalTransferred: 0,
    curingRemaining: 0,
    calculatedRemaining: 0,
    curingOutputDetailId: null
};

var curingItem = null;

data.forEach(function (item) {

    var status =
        String(item.status || "").trim();

    var reason =
        String(item.reason || "").trim();

    var total =
        Number(item.total || 0);

    if (total < 0) {
        total = 0;
    }

    if (status.toLowerCase() === "curing") {

        summary.curingRemaining += total;

        if (!curingItem) {
            curingItem = item;
        }
    }
    else if (status === "Stockyard (แกะดี)") {

        summary.stockyard += total;
    }
    else if (status.toLowerCase() === "reject") {

        if (!summary.rejects[reason]) {
            summary.rejects[reason] = 0;
        }

        summary.rejects[reason] += total;
        summary.totalReject += total;
    }
});

summary.totalTransferred =
    summary.stockyard +
    summary.totalReject;

summary.calculatedRemaining =
    summary.originalQty -
    summary.totalTransferred;

if (summary.calculatedRemaining < 0) {
    summary.calculatedRemaining = 0;
}

if (curingItem) {

    summary.curingOutputDetailId =
        curingItem.productionOrderOutputDetailID;
}

msg.batchState.pisSummary =
    summary;

msg.batchState.pisOutputDetails =
    data;

msg.batchState.fromOutputDetailId =
    summary.curingOutputDetailId;

msg.pisSummary =
    summary;

return msg;

// =====================================================
// BUILD SEND PREVIEW BATCH
//
// ใช้ Logic เดียวกับ Single SEND LOT DEPALLET
//
// PIS LIVE STATE = MASTER STARTING POINT
//
// 1. GET OutputDetails ใหม่ทุก Lot
// 2. ใช้ Curing ID + Remaining จาก PIS
// 3. Local ใช้เฉพาะ LotDepID + DateDepallet ที่ Batch เลือก
// 4. TargetSendTotal = MIN(LocalCuring, PISAvailable)
// 5. รักษา Reject ของ block ปัจจุบัน
// 6. Good ใช้ Capacity ที่เหลือ
//
// UPDATE DATE:
// Date = DateDepallet
// Time = dt โดยใช้ UTC getter
//
// ตัวอย่าง:
// DateDepallet = 2026-09-15T00:00:00.000Z
// dt           = 2026-09-15T18:15:56.840Z
//
// Result:
// updateDate   = 2026-09-15T18:15
// =====================================================


// =====================================================
// VALIDATE
// =====================================================

if (
    !msg.batchState ||
    !msg.batchState.pisSummary
) {
    node.error("BATCH PIS summary missing");
    return null;
}

if (
    !Array.isArray(msg.payload) ||
    msg.payload.length === 0
) {
    node.error(
        "Cumulative PIS_REJECT not found for " +
        (
            msg.batchState.lotNo ||
            ""
        )
    );

    return null;
}


// =====================================================
// STATE
// =====================================================

var state =
    msg.batchState;

var pis =
    state.pisSummary;

var row =
    msg.payload[0];

var header =
    state.header || {};

var fromOutputDetailId =
    state.fromOutputDetailId;


// =====================================================
// HELPERS
// =====================================================

function n(v) {

    var x =
        Number(v);

    return isFinite(x)
        ? x
        : 0;
}


function pos(v) {

    return Math.max(
        0,
        n(v)
    );
}


// =====================================================
// UPDATE DATE
//
// สำคัญ:
//
// MSSQL / Node-RED:
//
// DateDepallet:
// 2026-09-15T00:00:00.000Z
//
// dt:
// 2026-09-15T18:15:56.840Z
//
// dt คือ Factory Time
//
// ห้ามใช้ getHours()
// เพราะ Node-RED จะ +7 ชั่วโมง
//
// DATE = DateDepallet
// TIME = UTC HH:mm จาก dt
//
// Result:
// 2026-09-15T18:15
// =====================================================

function isoMinute(
    dateDepallet,
    dt
) {

    if (
        !dateDepallet ||
        !dt
    ) {
        return "";
    }


    function p(x) {

        return String(x)
            .padStart(
                2,
                "0"
            );
    }


    // =================================================
    // DATE PART
    // =================================================

    var dateText =
        String(
            dateDepallet
        ).trim();

    var m =
        dateText.match(
            /^(\d{4}-\d{2}-\d{2})/
        );

    var ymd =
        "";


    if (m) {

        ymd =
            m[1];
    }

    else {

        var dd =
            new Date(
                dateDepallet
            );

        if (
            isNaN(
                dd.getTime()
            )
        ) {
            return "";
        }

        ymd =
            dd.getUTCFullYear() +
            "-" +
            p(
                dd.getUTCMonth() + 1
            ) +
            "-" +
            p(
                dd.getUTCDate()
            );
    }


    // =================================================
    // TIME PART
    //
    // ใช้ UTC getter
    // เพื่อรักษาเวลา Factory
    // =================================================

    var td =
        new Date(dt);

    if (
        isNaN(
            td.getTime()
        )
    ) {
        return "";
    }

    var hh =
        p(
            td.getUTCHours()
        );

    var mm =
        p(
            td.getUTCMinutes()
        );


    return (
        ymd +
        "T" +
        hh +
        ":" +
        mm
    );
}


// =====================================================
// LOCAL MASTER TOTALS
//
// RejectTotal = CuringCnt - ToPackCnt
// =====================================================

var localCuring =
    pos(
        row.CuringCnt
    );

var localGood =
    pos(
        row.ToPackCnt
    );

var localRejectTotal =
    Math.max(
        0,
        localCuring -
        localGood
    );

var localTotal =
    localGood +
    localRejectTotal;


// =====================================================
// REJECT REASON MAP
//
// R99 = Other / Balance
// จึงไม่อยู่ใน normalReasonMap
// =====================================================

var normalReasonMap = {

    R01: "Rej_R01",
    R02: "Rej_R02",
    R03: "Rej_R03",
    R04: "Rej_R04",
    R05: "Rej_R05",
    R06: "Rej_R06",
    R08: "Rej_R08",
    R12: "Rej_R12",
    R13: "Rej_R13"
};


// =====================================================
// NORMAL REJECT TOTAL
// =====================================================

var normalRejectTotal =
    0;

Object.keys(
    normalReasonMap
).forEach(
    function (reason) {

        normalRejectTotal +=
            pos(
                row[
                    normalReasonMap[
                        reason
                    ]
                ]
            );
    }
);


// =====================================================
// R99 DEBUG
// =====================================================

var r99View =
    pos(
        row.Rej_R99
    );

var r99Raw =
    n(
        row.Rej_R99_Raw
    );


// =====================================================
// FINAL R99
//
// RejectTotal = MASTER
//
// FinalR99 = RejectTotal - SUM(normal reasons)
// =====================================================

var calculatedR99 =
    localRejectTotal -
    normalRejectTotal;

var rejectReasonValid =
    calculatedR99 >= 0;

var finalR99 =
    rejectReasonValid
        ? calculatedR99
        : 0;

var finalRejectByReason =
    normalRejectTotal +
    finalR99;


// =====================================================
// PIS LIVE STATE
// =====================================================

var originalQty =
    pos(
        pis.originalQty
    );

var pisGood =
    pos(
        pis.stockyard
    );

var pisReject =
    pos(
        pis.totalReject
    );

var pisTransferred =
    pos(
        pis.totalTransferred
    );


// =====================================================
// PIS AVAILABLE
//
// GET OutputDetails ล่าสุดเป็น MASTER
// =====================================================

var pisAvailable =
    pos(
        pis.curingRemaining
    );


// =====================================================
// CROSS CHECK ONLY
// =====================================================

var calculatedRemaining =
    Math.max(
        0,
        originalQty -
        pisTransferred
    );

var pisTotal =
    pisTransferred +
    pisAvailable;


// =====================================================
// PIS LIVE READY
// =====================================================

var pisLiveReady =

    !!fromOutputDetailId &&

    pisAvailable > 0;


// =====================================================
// TARGET SEND
//
// ตัวอย่าง 18P:
//
// LocalCuring  = 22680
// PISAvailable = 22675
//
// Target       = 22675
// =====================================================

var targetSendTotal =

    pisLiveReady

        ? Math.min(
            localCuring,
            pisAvailable
        )

        : 0;


// =====================================================
// MASTER DATA
// =====================================================

var machine =
    String(
        header.Machine ||
        ""
    ).trim();

var plant =
    String(
        header.plantCode ||
        ""
    ).trim();

var shift =
    String(
        row.ShiftID ||
        header.shiftCode ||
        ""
    ).trim();


// =====================================================
// UPDATE DATE
//
// ใช้ DateDepallet + dt
// =====================================================

var updateDate =
    isoMinute(
        row.DateDepallet,
        row.dt
    );


// =====================================================
// BUILD changeTo
//
// Reject ก่อน
// Good ใช้ Capacity ที่เหลือ
// =====================================================

var changeTo =
    [];

var sendGood =
    0;

var sendReject =
    0;

var totalSendQty =
    0;


// =====================================================
// PUSH CHANGE
// =====================================================

function pushChange(
    quantity,
    reasonCode,
    status
) {

    quantity =
        pos(
            quantity
        );

    if (
        quantity <= 0
    ) {
        return 0;
    }


    changeTo.push({

        machine:
            machine,

        quantity:
            quantity,

        reasonCode:
            reasonCode,

        remark:
            "",

        Shift:
            shift,

        status:
            status,

        updateDate:
            updateDate
    });


    totalSendQty +=
        quantity;


    return quantity;
}


// =====================================================
// BUILD FROM CURRENT PIS AVAILABLE
// =====================================================

if (
    pisLiveReady &&
    localCuring > 0 &&
    rejectReasonValid
) {

    // =================================================
    // Reject ทั้ง block ต้องใส่ใน PIS ได้
    //
    // ถ้า PISAvailable < LocalRejectTotal
    // BLOCK ไม่ตัด Reject ทิ้ง
    // =================================================

    if (
        pisAvailable >=
        localRejectTotal
    ) {

        // =============================================
        // NORMAL REJECT
        // =============================================

        Object.keys(
            normalReasonMap
        ).forEach(
            function (reason) {

                var qty =
                    pos(
                        row[
                            normalReasonMap[
                                reason
                            ]
                        ]
                    );

                if (
                    qty <= 0
                ) {
                    return;
                }

                sendReject +=
                    pushChange(
                        qty,
                        reason,
                        "Reject"
                    );
            }
        );


        // =============================================
        // R99
        // =============================================

        if (
            finalR99 > 0
        ) {

            sendReject +=
                pushChange(
                    finalR99,
                    "R99",
                    "Reject"
                );
        }


        // =============================================
        // GOOD AVAILABLE
        //
        // Target - Reject
        // =============================================

        var goodAvailable =
            targetSendTotal -
            sendReject;

        if (
            goodAvailable < 0
        ) {
            goodAvailable =
                0;
        }


        sendGood =
            Math.min(
                localGood,
                goodAvailable
            );


        if (
            sendGood > 0
        ) {

            pushChange(
                sendGood,
                "",
                "Stockyard (แกะดี)"
            );
        }
    }
}


// =====================================================
// STATUS
// =====================================================

var status =
    "";


// =====================================================
// 1. PIS ไม่มี Curing Balance
// =====================================================

if (
    pisAvailable <= 0
) {

    if (
        pisTransferred >=
        originalQty
    ) {

        status =
            "ALREADY SENT";
    }

    else {

        status =
            "NO PIS CURING BALANCE";
    }
}


// =====================================================
// 2. ไม่มี Curing ID
// =====================================================

else if (
    !fromOutputDetailId
) {

    status =
        "NO CURING ID";
}


// =====================================================
// 3. ไม่มี Local Depallet
// =====================================================

else if (
    localCuring <= 0
) {

    status =
        "NO LOCAL DEPALLET";
}


// =====================================================
// 4. Good > Curing
// =====================================================

else if (
    localGood >
    localCuring
) {

    status =
        "GOOD > LOCAL CURING";
}


// =====================================================
// 5. Local block > Original
// =====================================================

else if (
    localCuring >
    originalQty
) {

    status =
        "LOCAL CURING > ORIGINAL";
}


// =====================================================
// 6. Reject reasons เกิน TotalReject
// =====================================================

else if (
    !rejectReasonValid
) {

    status =
        "REJECT REASON > TOTAL REJECT";
}


// =====================================================
// 7. Reject Balance
// =====================================================

else if (
    finalRejectByReason !==
    localRejectTotal
) {

    status =
        "REJECT BALANCE ERROR";
}


// =====================================================
// 8. PIS เหลือน้อยกว่า Reject
// =====================================================

else if (
    pisAvailable <
    localRejectTotal
) {

    status =
        "PIS REMAIN < LOCAL REJECT";
}


// =====================================================
// 9. ไม่มีอะไรส่ง
// =====================================================

else if (
    totalSendQty <= 0
) {

    status =
        "NO DELTA";
}


// =====================================================
// 10. Send ห้ามเกิน PIS
// =====================================================

else if (
    totalSendQty >
    pisAvailable
) {

    status =
        "SEND QTY > PIS REMAIN";
}


// =====================================================
// 11. Send ห้ามเกิน Local block
// =====================================================

else if (
    totalSendQty >
    localCuring
) {

    status =
        "SEND QTY > LOCAL CURING";
}


// =====================================================
// 12. Good + Reject ต้องเท่ากับ SendTotal
// =====================================================

else if (
    (
        sendGood +
        sendReject
    ) !==
    totalSendQty
) {

    status =
        "SEND BALANCE ERROR";
}


// =====================================================
// 13. MASTER DATA
// =====================================================

else if (
    !machine
) {

    status =
        "MACHINE MISSING";
}

else if (
    !plant
) {

    status =
        "PLANT MISSING";
}

else if (
    !shift
) {

    status =
        "SHIFT MISSING";
}

else if (
    !updateDate
) {

    status =
        "UPDATE DATE MISSING";
}


// =====================================================
// READY
// =====================================================

else {

    status =
        "READY";
}


// =====================================================
// DEFAULT
//
// ไม่สร้าง POST จนกว่าจะ READY
// =====================================================

state.changeStatusPayload =
    null;


// =====================================================
// PREVIEW
// =====================================================

var preview = {

    LotDepID:
        state.lotNo,

    DateDepallet:
        row.DateDepallet,

    DtSource:
        row.dt,


    // ---------------------------------
    // LOCAL
    // ---------------------------------

    LocalCuring:
        localCuring,

    LocalGood:
        localGood,

    LocalRejectTotal:
        localRejectTotal,

    LocalTotal:
        localTotal,


    // ---------------------------------
    // REJECT
    // ---------------------------------

    NormalRejectTotal:
        normalRejectTotal,

    R99View:
        r99View,

    R99Raw:
        r99Raw,

    R99Balance:
        calculatedR99,

    FinalR99:
        finalR99,

    FinalRejectByReason:
        finalRejectByReason,

    RejectReasonValid:
        rejectReasonValid,


    // ---------------------------------
    // PIS LIVE
    // ---------------------------------

    PISOutputDetailId:
        fromOutputDetailId
            ? String(
                fromOutputDetailId
            )
            : "",

    OriginalQty:
        originalQty,

    PISGood:
        pisGood,

    PISReject:
        pisReject,

    PISTransferred:
        pisTransferred,

    PISAvailable:
        pisAvailable,

    PISRemain:
        pisAvailable,

    CalculatedRemain:
        calculatedRemaining,

    PISTotal:
        pisTotal,


    // ---------------------------------
    // SEND
    // ---------------------------------

    TargetSendTotal:
        targetSendTotal,

    UpdateDate:
        updateDate,

    SendMode:
        pisLiveReady
            ? "PIS LIVE CURING ID"
            : "NO PIS CURING ID/BALANCE",

